# What drives the small GAMLSS standard errors: the subject effect, the zeros, or a between-subject term? Null group effect throughout.
suppressPackageStartupMessages({library(gamlss);library(glmmTMB);library(parallel)}); a<-commandArgs(TRUE); nrep<-as.integer(a[2])
gr<-expand.grid(sdu=c(0,.5),prev=c(1,.6,.15),term=c("between","within"),stringsAsFactors=FALSE)
sim<-function(de){n<-40;m<-4; id<-factor(rep(seq_len(n),each=m)); g<-if(de$term=="between") factor(rep(rep(c("a","b"),length.out=n),each=m)) else factor(rep(c("a","b"),length.out=n*m)); age<-runif(n*m,0,6); u<-rnorm(n,sd=de$sdu)[id]; mu<-plogis(-3+u+.1*age); phi<-20; y<-rbeta(n*m,mu*phi,(1-mu)*phi); y[runif(n*m)>de$prev]<-0; data.frame(y=y,g=g,age=age,id=id)}
gam<-function(d,cyc,rand){f<-if(rand) y~g+age+random(id) else y~g+age; m<-suppressWarnings(try(gamlss(f,family=BEZI,data=d,trace=FALSE,control=gamlss.control(n.cyc=cyc,trace=FALSE)),silent=TRUE)); if(inherits(m,"try-error")) return(c(est=NA,se=NA,p=NA,conv=NA)); capture.output(s<-suppressWarnings(try(summary(m,save=TRUE),silent=TRUE))); if(inherits(s,"try-error")||!"gb"%in%rownames(s$coef.table)) return(c(est=NA,se=NA,p=NA,conv=m$converged)); k<-s$coef.table["gb",]; c(est=k[[1]],se=k[[2]],p=k[[4]],conv=m$converged)}
tmb<-function(d){m<-suppressWarnings(suppressMessages(try(glmmTMB(y~g+age+(1|id),ziformula=if(any(d$y==0)) ~1 else ~0,family=beta_family(),data=d),silent=TRUE))); if(inherits(m,"try-error")) return(c(est=NA,se=NA,p=NA,conv=NA)); s<-try(summary(m)$coefficients$cond,silent=TRUE); if(inherits(s,"try-error")) return(c(est=NA,se=NA,p=NA,conv=NA)); c(est=s["gb",1],se=s["gb",2],p=s["gb",4],conv=isTRUE(m$sdr$pdHess))}
one<-function(r,de){set.seed(2000+r); d<-sim(de); rbind(data.frame(method="gamlss20_random",t(gam(d,20,TRUE))),data.frame(method="gamlss100_norandom",t(gam(d,100,FALSE))),data.frame(method="glmmTMB",t(tmb(d))))}
res<-list(); for(i in seq_len(nrow(gr))){de<-gr[i,]; x<-do.call(rbind,mclapply(seq_len(nrep),one,de=de,mc.cores=2)); x$sdu<-de$sdu; x$prev<-de$prev; x$term<-de$term; res[[i]]<-x; saveRDS(res,a[1]); cat(i,"of",nrow(gr),"\n")}
cat("done\n")
